// Asset loader: sprite sheets, props atlas, backgrounds and the pixel font are generated by tools/art (original art).
const img = src => new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = () => rej(new Error('asset ' + src)); i.src = src; });
export const A = { meta: null, sheets: {}, flash: {}, props: null, propsImg: null, font: null, bg: {}, ready: false };
const STAGES_BG = ['zoo', 'street', 'river', 'night', 'jungle'], LAYERS = ['sky', 'far', 'mid', 'near', 'ground'];
export async function loadAssets() {
  const meta = await (await fetch('assets/sprites.json')).json();
  A.meta = meta; A.props = await (await fetch('assets/props.json')).json();
  const jobs = [];
  for (const k of Object.keys(meta)) { jobs.push(img(`assets/${k}.png`).then(i => A.sheets[k] = i)); jobs.push(img(`assets/${k}_f.png`).then(i => A.flash[k] = i)); }
  jobs.push(img('assets/props.png').then(i => A.propsImg = i), img('assets/font.png').then(i => A.font = i));
  for (const s of STAGES_BG) { A.bg[s] = {}; for (const l of LAYERS) jobs.push(img(`assets/bg_${s}_${l}.png`).then(i => A.bg[s][l] = i)); }
  await Promise.all(jobs); A.ready = true;
}
